// 📁 src/context/AuthContext.jsx
import { createContext, useContext, useEffect, useMemo, useState } from "react";
import { jwtDecode } from "jwt-decode";
import api from "@/utils/api";
import { safeLocal, safeSession } from "@/utils/safeStorage";

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [admin, setAdmin] = useState(null);
  const [loading, setLoading] = useState(true);
  const [initialCheckDone, setInitialCheckDone] = useState(false);

  // -- Helpers de stockage --
  const getRemember = () =>
    (safeLocal.get("adminRemember") || safeSession.get("adminRemember")) === "1";

  const getStoredToken = () =>
    safeLocal.get("adminToken") || safeSession.get("adminToken");

  const getStoredUser = () => {
    const raw = safeLocal.get("adminUser") || safeSession.get("adminUser");
    if (!raw) return null;
    try {
      return JSON.parse(raw);
    } catch {
      return null;
    }
  };

  const setAuthHeader = (token) => {
    if (token) {
      api.defaults.headers.common["Authorization"] = `Bearer ${token}`;
    } else {
      delete api.defaults.headers.common["Authorization"];
    }
  };

  // -- Réhydratation au premier rendu --
  useEffect(() => {
    try {
      const token = getStoredToken();
      const user = getStoredUser();

      if (token && user) {
        setAdmin(user);
        setAuthHeader(token);

        // (optionnel) on peut décoder pour vérifier expiration
        try {
          const { exp } = jwtDecode(token);
          if (exp && Date.now() >= exp * 1000) {
            // expiré → logout silencieux
            doLogout(false);
          }
        } catch {
          // token illisible → on laisse l’utilisateur se reconnecter
        }
      } else {
        setAuthHeader(null);
      }
    } finally {
      setLoading(false);
      setInitialCheckDone(true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // -- LOGIN --
  const login = (token, adminObj, rememberMe = true) => {
    const storage = rememberMe ? safeLocal : safeSession;
    // marqueur de persistence
    if (rememberMe) {
      safeLocal.set("adminRemember", "1");
      safeSession.remove("adminRemember");
    } else {
      safeSession.set("adminRemember", "1");
      safeLocal.remove("adminRemember");
    }

    storage.set("adminToken", token);
    storage.set("adminUser", JSON.stringify(adminObj));

    setAuthHeader(token);
    setAdmin(adminObj);
  };

  // -- LOGOUT --
  const doLogout = (clearRemember = true) => {
    // On purge partout sans throw
    safeLocal.remove("adminToken");
    safeLocal.remove("adminUser");
    if (clearRemember) safeLocal.remove("adminRemember");

    safeSession.remove("adminToken");
    safeSession.remove("adminUser");
    if (clearRemember) safeSession.remove("adminRemember");

    setAuthHeader(null);
    setAdmin(null);
  };

  const value = useMemo(
    () => ({
      admin,
      loading,
      initialCheckDone,
      login,
      logout: () => doLogout(true),
      // utilitaires si besoin ailleurs
      getStoredToken,
      getStoredUser,
      getRemember,
    }),
    [admin, loading, initialCheckDone]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export const useAuth = () => useContext(AuthContext);
