// 📁 src/utils/api.js
import axios from "axios";
import { safeLocal, safeSession } from "@/utils/safeStorage";

const api = axios.create({
  baseURL: "/backend",
  withCredentials: true,
});

api.interceptors.request.use((config) => {
  const token = safeLocal.get("adminToken") || safeSession.get("adminToken") || null;
  if (token) config.headers.Authorization = `Bearer ${token}`;
  else delete config.headers.Authorization;
  return config;
});

api.interceptors.response.use(
  (res) => res,
  (error) => {
    const msg = error?.response?.data?.message;
    if (error?.response?.status === 401) {
      if (msg) console.warn("401:", msg);
      window.location.href = "/admin/login";
    } else if (error?.response?.status === 403) {
      if (msg) console.warn("403:", msg);
      safeLocal.remove("adminToken");
      safeLocal.remove("adminUser");
      safeSession.remove("adminToken");
      safeSession.remove("adminUser");
      window.location.href = "/admin/login";
    }
    return Promise.reject(error);
  }
);

export default api;
